import React from 'react';
import HelpOutlineIcon from '@material-ui/icons/HelpOutline';
import { SwitchNew } from '@getvim/atomic-ui';
import './index.scss';

export interface LoginContentProps {
  value: boolean;
  onChange: (value: boolean) => void;
  onReadMoreClick: () => void;
}

export const LoginContent: React.FC<LoginContentProps> = ({ value, onChange, onReadMoreClick }) => {
  return (
    <div className="login-content">
      <span onClick={onReadMoreClick} role="button" tabIndex={0}>
        <HelpOutlineIcon />
        <span className="learn-more">Learn more</span>
      </span>
      <SwitchNew value={value} onChange={(_, isChecked) => onChange(isChecked)} checked={value} />
    </div>
  );
};
